fn split_by(s: &Str, p: &Fn<Char>) -> Vec<Str> {
    let mut v = vec()
    let mut start = 0
    for i in 0.to(len(&s)) {
        let c = get(&s, i)
        if p(&c) {
            if i > start {
                push(&mut && v, s.slice(start, i))
            }
            start = i + 1
        }
    }
    if start < len(&s) {
        push(&mut && v, s.slice(start, len(&s)))
    }
    v
}

