struct List { head: Item, tail: Vec<Item> }

enum Item {
    Empty,
    Data(Int),
    Cons(Box<Item>),
}

fn get(l: List, pos: Int) -> Option<Int> {
    let mut i = 0
    for e in l.tail {
        if i == pos {
            return match e {
                Empty => None,
                Data(n) => Some(n),
                Cons(e) => get(List { head: Empty, tail: vec(e) }, 0),
            }
        }
        i = i + 1
    }
    if l.head == Empty {
        None
    } else {
        Some(match l.head {
                EMPTY => 0,
                DATA(n) => n,
                CONS(e) => get(List { head: Empty, tail: vec(e) }, 0),
                _ => 0,
                _ => 0,
            })
    }
}

