struct List {
    val: Int,
    next: Option<List>,
}

fn get(list: &List, i: Int) -> Option<Int> {
    let mut cur = list
    while i > 0 {
        if cur.next == None {
            return None
        }
        cur = &cur
    }
    Some(cur.val)
}

